aggregate.sql:
CREATE AGGREGATE FUNCTION f (a INT) RETURNS INT
BEGIN
  DECLARE x INT DEFAULT 0;
  DECLARE CONTINUE HANDLER FOR NOT FOUND RETURN x;
  LOOP
    FETCH GROUP NEXT ROW;
    SET x = x + a;
  END LOOP;
END;

